#pragma once
static const char SETTINGS_SCRIPT[] = R"HTML(
<script>
const form=document.getElementById('settingsform');
for(const button of document.querySelectorAll('[data-password]'))button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.password);const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Verbergen':'Anzeigen';button.setAttribute('aria-pressed',String(show));});
const message=document.getElementById('filemessage');
document.getElementById('export').addEventListener('click',()=>{const fields={};for(const input of form.elements){if(!input.name||input.name==='token'||input.type==='password'||input.dataset.secret==='yes'||input.name.startsWith('clear_'))continue;if(input.type==='checkbox')fields[input.name]=input.checked?'1':'0';else fields[input.name]=input.value;}const blob=new Blob([JSON.stringify({version:1,fields},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='sparkminer-einstellungen.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.textContent='Datei ohne Kennwörter erstellt. Noch nicht gespeicherte Formularwerte sind enthalten.';});
document.getElementById('restore').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>16384)throw Error('Datei zu groß.');const data=JSON.parse(await file.text());if(data.version!==1||!data.fields||Array.isArray(data.fields)||typeof data.fields!=='object')throw Error('Unbekanntes Dateiformat.');for(const [name,value]of Object.entries(data.fields)){const input=form.elements.namedItem(name);if(!input||!input.name||input.name==='token'||input.dataset.secret==='yes'||input.name.startsWith('clear_')||typeof value!=='string')throw Error('Unzulässiges Feld in der Datei.');}for(const [name,value]of Object.entries(data.fields)){const input=form.elements.namedItem(name);if(input.type==='checkbox')input.checked=value==='1';else input.value=value;}message.textContent='Werte ins Formular übernommen. Kennwörter bleiben erhalten. Bitte prüfen und speichern.';}catch(error){message.textContent='Import fehlgeschlagen: '+error.message;}event.target.value='';});
for(const button of document.querySelectorAll('[data-action]'))button.addEventListener('click',()=>{const action=button.dataset.action;const words={restart:'NEUSTART',stats_reset:'STATISTIK LOESCHEN',factory:'WERKSRESET'};const word=words[action];const entered=prompt(button.dataset.question+'\nZur Bestätigung eingeben: '+word);if(entered!==word)return;const f=document.getElementById('actionform');f.elements.action.value=action;f.elements.confirmation.value=entered;f.submit();});
async function mailAction(probe){
if(!probe&&!confirm('Testmail an die gespeicherte Empfaengeradresse senden?'))return;
const buttons=[document.getElementById('mail-test'),document.getElementById('mail-probe')];for(const b of buttons)b.disabled=true;
const output=document.getElementById('mail-status');try{const data=new URLSearchParams({token:form.elements.token.value,confirmation:'TESTMAIL'});const response=await fetch(probe?'/settings/mail-probe':'/settings/mail-test',{method:'POST',body:data});if(!response.ok)throw Error(await response.text());output.textContent=probe?'Verbindungspruefung angefordert …':'Testmail angefordert …';for(let i=0;i<35;i++){await new Promise(resolve=>setTimeout(resolve,2000));const r=await fetch('/api/mail-status',{cache:'no-store'});if(!r.ok)throw Error('Mailstatus nicht erreichbar.');const state=await r.json();output.textContent=state.message;if(!/angefordert|wird versendet/.test(state.message))break;}}catch(error){output.textContent=error.message;}finally{for(const b of buttons)b.disabled=false;}}
const mailButton=document.getElementById('mail-test');if(mailButton){mailButton.addEventListener('click',()=>mailAction(false));document.getElementById('mail-probe').addEventListener('click',()=>mailAction(true));}
</script>
)HTML";
